-- ============================================================
-- Lido - SEED MARINE / PUNTI D'IMBARCO (fonte OpenStreetMap)
-- 876 marine/porti con nome. tipo='marina'. Esegui DOPO 0003 e 0005.
-- Dedup su (nome,localita). Idempotente.
-- ============================================================
on conflict (nome, localita) do update set
  regione=excluded.regione, lat=excluded.lat, lng=excluded.lng,
  categoria=excluded.categoria, tipo=excluded.tipo, fonte=excluded.fonte;
